    {
        if (_defaultStoreId.HasValue)
            return _defaultStoreId.Value;

        var store = await Table<Store>().FirstOrDefaultAsync() ?? throw new Exception("No default store could be loaded");

        _defaultStoreId = store.Id;

        return store.Id;
    }

